const nodemailer = require('nodemailer');
const config = require('./config');

let transporte = null;
const usaGmailApi = () => Boolean(config.gmailApi.clientId && config.gmailApi.clientSecret && config.gmailApi.refreshToken);
const configurado = () => usaGmailApi() || Boolean(config.smtp.host && config.smtp.user && config.smtp.pass);

// ---------- Gmail API (HTTPS): funciona en Render gratis, donde el SMTP está bloqueado ----------
let tokenCache = { valor: '', vence: 0 };

async function tokenGmail() {
  if (tokenCache.valor && Date.now() < tokenCache.vence - 60000) return tokenCache.valor;
  const r = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      client_id: config.gmailApi.clientId,
      client_secret: config.gmailApi.clientSecret,
      refresh_token: config.gmailApi.refreshToken,
      grant_type: 'refresh_token',
    }),
    signal: AbortSignal.timeout(10000),
  });
  const d = await r.json().catch(() => ({}));
  if (!r.ok || !d.access_token) {
    throw new Error(`Gmail OAuth: ${d.error_description || d.error || r.status}`);
  }
  tokenCache = { valor: d.access_token, vence: Date.now() + (d.expires_in || 3600) * 1000 };
  return tokenCache.valor;
}

async function enviarPorGmailApi(opciones) {
  // nodemailer arma el mensaje completo (HTML + imágenes) y la API de Gmail lo envía
  const { message } = await nodemailer
    .createTransport({ streamTransport: true, buffer: true, newline: 'unix' })
    .sendMail(opciones);
  const token = await tokenGmail();
  const r = await fetch('https://gmail.googleapis.com/gmail/v1/users/me/messages/send', {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ raw: message.toString('base64url') }),
    signal: AbortSignal.timeout(15000),
  });
  if (!r.ok) {
    const d = await r.json().catch(() => ({}));
    throw new Error(`Gmail API: ${(d.error && d.error.message) || r.status}`);
  }
}

function obtenerTransporte() {
  if (!transporte) {
    transporte = nodemailer.createTransport({
      host: config.smtp.host,
      port: config.smtp.port,
      secure: config.smtp.secure,
      auth: { user: config.smtp.user, pass: config.smtp.pass },
    });
  }
  return transporte;
}

const escapar = (t) =>
  String(t).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

// Imágenes del correo: van incrustadas en este mismo archivo y se envían como adjuntos CID,
// así el correo se ve igual sin depender de ningún servidor ni de otras carpetas.
const DATOS_IMG = {
  encabezado: '',
  sobre: '',
  escudo: '',
  reloj: '',
};
const IMAGENES = Object.entries(DATOS_IMG).map(([n, b64]) => ({
  filename: `${n}.png`,
  content: Buffer.from(b64, 'base64'),
  contentType: 'image/png',
  cid: `${n}@secretgift`,
}));

const FUENTE = "'Poppins','Segoe UI',Helvetica,Arial,sans-serif";
const AZUL = '#1060e8';
const MARINO = '#0b1a55';
const GRIS = '#5f6f90';

/** Plantilla del correo con el código (verificar cuenta o recuperar contraseña). */
function plantilla({ codigo, recuperar }) {
  const titulo = recuperar ? '¡Restablece tu contraseña!' : '¡Verifica tu correo!';
  const intro = recuperar
    ? `Usa el siguiente código para restablecer la contraseña de tu cuenta en <b style="color:${AZUL}">SecretGift</b>.`
    : `Usa el siguiente código de verificación para completar el registro de tu cuenta en <b style="color:${AZUL}">SecretGift</b>.`;
  const seguridad = recuperar
    ? 'Si no solicitaste este código, ignora este mensaje: tu contraseña no cambiará.'
    : 'Si no solicitaste este código, puedes ignorar este mensaje.';

  const cuadros = String(codigo)
    .split('')
    .map(
      (d) => `<td width="16.66%" style="padding:0 3px">
        <div style="background:#ffffff;border:1px solid #d3e3fb;border-radius:12px;height:58px;line-height:58px;text-align:center;font-family:${FUENTE};font-size:34px;font-weight:700;color:${AZUL}">${d}</div>
      </td>`,
    )
    .join('');

  const lado = 'border-left:1px solid #e3ecf9;border-right:1px solid #e3ecf9;background:#fbfdff';

  return `<!DOCTYPE html>
<html lang="es">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:0;background:#eef4fc">
  <div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent">Tu código es ${codigo}. Vence en 10 minutos.</div>
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef4fc">
    <tr><td align="center" style="padding:26px 12px">
      <table role="presentation" width="480" cellpadding="0" cellspacing="0" style="width:100%;max-width:480px;font-family:${FUENTE}">

        <!-- Encabezado: olas + logo -->
        <tr><td style="font-size:0;line-height:0">
          <img src="cid:encabezado@secretgift" alt="SecretGift" width="480" style="display:block;width:100%;max-width:480px;height:auto;border:0;border-radius:22px 22px 0 0">
        </td></tr>

        <!-- Sobre -->
        <tr><td align="center" style="${lado};padding:6px 20px 0">
          <img src="cid:sobre@secretgift" alt="" width="230" style="display:block;width:230px;max-width:80%;height:auto;border:0">
        </td></tr>

        <!-- Título y texto -->
        <tr><td align="center" style="${lado};padding:14px 32px 0">
          <h1 style="margin:0;font-family:${FUENTE};font-size:29px;line-height:36px;font-weight:700;color:${MARINO}">${titulo}</h1>
          <p style="margin:12px 0 0;font-family:${FUENTE};font-size:16px;line-height:25px;color:${GRIS}">${intro}</p>
        </td></tr>

        <!-- Código -->
        <tr><td style="${lado};padding:26px 22px 0">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#e9f2fd;border:1px solid #cfe1fa;border-radius:18px">
            <tr><td style="padding:18px 12px">
              <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>${cuadros}</tr></table>
            </td></tr>
          </table>
        </td></tr>

        <!-- Vencimiento -->
        <tr><td align="center" style="${lado};padding:20px 20px 0">
          <table role="presentation" cellpadding="0" cellspacing="0"><tr>
            <td style="padding-right:8px;font-size:0;line-height:0"><img src="cid:reloj@secretgift" alt="" width="20" height="20" style="display:block;border:0"></td>
            <td style="font-family:${FUENTE};font-size:15px;color:${GRIS}">Este código vence en 10 minutos.</td>
          </tr></table>
        </td></tr>

        <!-- Por tu seguridad -->
        <tr><td style="${lado};padding:22px 22px 0">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eff4fc;border-radius:16px">
            <tr>
              <td width="64" align="center" valign="middle" style="padding:18px 0 18px 14px;font-size:0;line-height:0">
                <img src="cid:escudo@secretgift" alt="" width="34" style="display:block;width:34px;height:auto;border:0">
              </td>
              <td valign="middle" style="padding:16px 18px 16px 10px;font-family:${FUENTE}">
                <div style="font-size:15px;font-weight:700;color:${MARINO}">Por tu seguridad</div>
                <div style="font-size:13.5px;line-height:21px;color:${GRIS};margin-top:3px">${seguridad}</div>
              </td>
            </tr>
          </table>
        </td></tr>

        <!-- Pie -->
        <tr><td style="${lado};padding:26px 30px 0">
          <div style="border-top:1px solid #e3ecf9;font-size:0;line-height:0">&nbsp;</div>
        </td></tr>
        <tr><td align="center" style="${lado};border-bottom:1px solid #e3ecf9;border-radius:0 0 22px 22px;padding:16px 20px 26px;font-family:${FUENTE};font-size:14px;color:${GRIS}">
          <b style="color:${AZUL}">SecretGift</b> &nbsp;·&nbsp; Regala momentos especiales
        </td></tr>

      </table>
    </td></tr>
  </table>
</body>
</html>`;
}

async function enviarCodigo(correo, nombre, codigo, tipo = 'verificar') {
  if (!configurado()) {
    if (config.produccion) throw new Error('El correo (SMTP) no está configurado.');
    console.log(`\n[DESARROLLO] Código de verificación para ${correo}: ${codigo} (${tipo})\n`);
    return { simulado: true };
  }

  const recuperar = tipo === 'recuperar';
  const asunto = recuperar ? 'Restablece tu contraseña - SecretGift' : 'Verifica tu correo - SecretGift';
  const intro = recuperar ? 'usa este código para restablecer tu contraseña:' : 'usa este código para verificar tu correo:';
  const aviso = recuperar ? 'Si no lo solicitaste, ignora este mensaje: tu contraseña no cambiará.' : 'Si no creaste una cuenta, ignora este mensaje.';
  const texto = `Hola ${nombre},\n\n${intro} ${codigo}\n\nVence en 10 minutos. ${aviso}`;

  const mensaje = {
    from: config.smtp.from,
    to: correo,
    subject: asunto,
    text: texto,
    html: plantilla({ codigo, recuperar }),
    attachments: IMAGENES,
  };
  if (usaGmailApi()) await enviarPorGmailApi(mensaje);
  else await obtenerTransporte().sendMail(mensaje);
  return { simulado: false };
}

module.exports = { enviarCodigo, configurado, plantilla, usaGmailApi };
